// === Tab: mySketch ===
// Attractor_16.0

let N = 4000 ; 
let S = 0.018 ; let G = 0.019 ; let H = 0.45 ; let R = screenWidth/4 ; let Q = 20 ;
//let S = 0.018 ; let G = 0.019 ; let H = 0.45 ; let R = 200 ; let Q = 20 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; let Z[] = new Array(N) ;
let L ; let dX ; let dY ; let dZ ; let P ; let U ;
let I ; let NX ; let NY ; let NZ ; let KN ;

function setup(){

  createCanvas(screenWidth, screenHeight) ; noSmooth() ; background(0) ; 
	 // createCanvas(1000, 1000) ; noSmooth() ; background(0) ; 
	//stroke(123,34,83) ;
	//textSize(20) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(+10,+180) ;
    Y[I] = random(-180,+180) ;
    Z[I] = random(+10,+180) ;

  }
  KN = N ;

}// setup()

function draw(){

  if ( KN == N ){ fill(0,0,0,40) ; rect(-1,-1,width,height) ; fill(0) ; }
//  line(50,400,550,400) ; line(550,400,540,390) ; line(550,400,540,410) ; text("X",560,405) ;
//  line(300,50,300,550) ; line(300,50,290,60) ; line(300,50,310,60) ; text("Z",295,40) ;
//  line(450,250,150,550) ; line(150,550,150,535) ; line(150,550,165,550) ; text("Y",130,570) ;

  for ( I = 0 ; I < KN ; I++ ){

    L = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
    P = (atan((L-R)/Z[I])+(PI/2))/PI ;
    U = abs(Y[I])/L ;
    dX = (-Z[I]*H*P*U*X[I]/L) + (L*G*X[I]/L) + (-Y[I]*S) + (Q*X[I]/pow(L,3)) ; 
    dY = (-Z[I]*H*P*U*Y[I]/L) + (L*G*Y[I]/L) + (+X[I]*S) + (Q*Y[I]/pow(L,3)) ; 
    dZ = ((L-R)*H*P*U) ;
    NX = X[I] + dX ; NY = Y[I] + dY ; NZ = Z[I] + dZ ;

		  line(X[I]-(Y[I]/2)+width/2,-Z[I]+(Y[I]/2)+height/2,NX-(NY/2)+width/2,-NZ+(NY/2)+height/2) ;
		    stroke(L,dZ*22,P);  
		line(Y[I]/2-(X[I])+width/2,-Y[I]/2+(Z[I])+height/2,NY/2-(NX)+width/2,-NY/2+(NZ)+height/2) ;
		stroke(L,dX*22,U);  
    X[I] = NX ; 
		Y[I] = NY ; 
		Z[I] = NZ ;    

  }// I

}// draw()

function mousePressed(){

  background(0) ;
  if ( KN != N ){
    for ( I = 1 ; I < N ; I++ ){
      X[I] = X[0] + random(-100,+100) ;
      Y[I] = Y[0] + random(-100,+100) ;
      Z[I] = Z[0] + random(-100,+100) ;
    }
    KN = N ;
  }else{ KN = 1 ; }

}// mousePressed()

